import json,subprocess
c=json.load(open('c1_fit.json'))
c['params']={'XL':c['params']['XL'],'Re':0.0,'mp':c['params']['mp'],'kpv':c['params']['kpv'],'kiv':c['params']['kiv'],'TPf':0.02,'kq':0.2,'kv':0.2,'TV':0.5,'w0':c['params']['w0']}
c['defs']={'Ei':'xv + kpv*(Vset - Vm) ' ,'dl':'delta - theta','Pe':'V*(Re*(Ei*cos(dl)-V)+XL*Ei*sin(dl))/(Re**2+XL**2)'}
c['states']={'delta':{'rhs':'w0*mp*(P0-Pm)','init':'theta0 + atan2((XL*P0)/V0, V0)'},
 'xv':{'rhs':'kiv*(Vset-Vm)','init':'V0'},
 'Pm':{'rhs':'(Pe-Pm)/TPf','init':'P0'},
 'Vm':{'rhs':'(V-Vm)/TV','init':'V0'}}
c['outputs']={'P':'Pe','Q':'Q0 + kq*(V-Vm) + kv*(Vset-V0)'}
json.dump(c,open('c2.json','w'),indent=1)
r=subprocess.run(['python','tools/fit_model.py','c2.json','--fix','w0,Re','--maxfev','120','--out','c2_fit.json'],capture_output=True,text=True)
print(r.stdout[-3000:],r.stderr[-1500:])

